"""
Script to validate spatial clustering proxies for all datasets and
write a consolidated validation report to
data/manifests/spatial_proxy_validation.json.
"""

import json
from pathlib import Path

import pandas as pd
import numpy as np

from llmxive_toolkit import paths, get_logger
from dependency_injector import (
    compute_proxy_silhouette_score,
    generate_spatial_proxy,
    validate_spatial_proxy,
    save_proxy_validation_report,
)

log = get_logger(__name__)

def main() -> None:
    # Load the existing proxy report (generated by generate_spatial_proxy.py)
    proxy_report_path = paths.data("manifests", "spatial_proxy_report.json")
    if not proxy_report_path.is_file():
        log.error(f"Proxy report not found at {proxy_report_path}")
        raise FileNotFoundError(f"Proxy report not found at {proxy_report_path}")

    with open(proxy_report_path, "r") as f:
        proxy_report = json.load(f)

    validation_results: Dict[str, Any] = {}

    for dataset_name, proxy_data in proxy_report.items():
        # Load the raw dataset (assume CSV; fallback to Excel if needed)
        raw_path_csv = paths.data("raw", f"{dataset_name}.csv")
        raw_path_xls = paths.data("raw", f"{dataset_name}.xls")
        if raw_path_csv.is_file():
            df = pd.read_csv(raw_path_csv, header=None)
        elif raw_path_xls.is_file():
            df = pd.read_excel(raw_path_xls, header=None)
        else:
            log.warning(f"Raw data file for dataset '{dataset_name}' not found; skipping.")
            continue

        data_array = df.values.astype(float)

        # If proxy was not generated (e.g., because of earlier failure), regenerate it
        if not proxy_data or not proxy_data.get("labels"):
            log.info(f"Generating proxy for dataset '{dataset_name}' on the fly.")
            proxy_data = generate_spatial_proxy(data_array, n_clusters=3)

        # Perform validation
        result = validate_spatial_proxy(data_array, proxy_data, threshold=0.25)
        validation_results[dataset_name] = result

    # Write consolidated validation report
    validation_path = paths.data("manifests", "spatial_proxy_validation.json")
    with open(validation_path, "w") as f:
        json.dump(validation_results, f, indent=2)

    log.info(f"Spatial proxy validation report written to {validation_path}")

if __name__ == "__main__":
    main()